# Convert non-serializable objects (e.g., Timestamps) to strings for JSON compatibility
def serialize_state(state):
    """Recursively converts non-serializable objects to serializable ones."""
    if isinstance(state, dict):
        return {k: serialize_state(v) for k, v in state.items()}
    elif isinstance(state, list):
        return [serialize_state(item) for item in state]
    elif isinstance(state, pd.Timestamp):
        return state.isoformat()  # Convert Timestamp to ISO 8601 string
    else:
        return state

# Serialize the enhanced framework
serializable_framework = serialize_state(final_enhanced_framework)

# Save to file for deployment
deployment_file = "/mnt/data/enhanced_framework_state_fixed.json"
with open(deployment_file, "w") as file:
    json.dump(serializable_framework, file)

# Confirm deployment
deployment_status_fixed = {
    "Status": "Deployment Successful",
    "FilePath": deployment_file,
    "Details": "Enhanced framework state successfully serialized and deployed."
}

deployment_status_fixed

